const DEC_YT_PIPELINE=[{"id": "YT-L01", "title": "РАППА 2026: обзор выставки для владельцев парков", "status": "Исходники найдены · нужен просмотр и монтаж", "target_duration": "4–6 минут, если пригодного материала достаточно", "proposed_date": "2026-12-13", "description": "Обзор выставки РАППА 2026 для тех, кто планирует или развивает развлекательный парк.\n\nUNITRAMP проектирует и строит комплексные детские и семейные парки.\nhttps://unitramp.ru/\n\n#РАППА2026 #ИндустрияРазвлечений #юнитрамп", "text_html": "<p>Вступление: где снят материал и что увидит зритель.</p>\n<p>Далее — два или три конкретных решения, которые действительно попали в исходную запись. Для каждого: общий вид, деталь, законченный комментарий участника. Если комментария нет, факт сначала проверяется, затем пишется отдельная озвучка.</p>\n<p>Завершение: какие вопросы стоит задать при выборе решения для своего парка. Только выводы, подтверждённые просмотренным материалом.</p>\n<p>Это монтажная структура. Дословные реплики и таймкоды будут добавлены после просмотра исходников.</p>"}, {"id": "YT-L02", "title": "Как собрать комплексный семейный парк из разных игровых зон", "status": "Готов сценарий · ждёт озвучки и монтажа", "target_duration": "4–5 минут", "proposed_date": "2026-12-20", "description": "Как собрать комплексный семейный парк из разных игровых зон.\n\nКак связать игры, вход, отдых и работу команды в одном семейном парке.\n\nUNITRAMP проектирует и строит комплексные детские и семейные парки.\nhttps://unitramp.ru/", "text_html": "<p>Семейный парк начинается с вопроса: как здесь проведёт время семья? Один ребёнок хочет сразу забраться повыше, другой выбирает спокойную игру, взрослым нужно убрать вещи и понять, где можно остаться рядом. Если рассматривать только список оборудования, эти задачи легко потерять. Поэтому будущий парк стоит проверять как целый визит, от входа до возвращения за вещами.</p>\n<p>Сначала определяем, для кого создаём пространство. Семья с малышом и школьником пользуется парком иначе, чем группа подростков. Для неё важно найти подходящие занятия в одном месте и договориться, где встретиться после игры. Этот сценарий помогает выбирать состав зон. Уже потом можно решать, какой лабиринт нужен, где появится интерактив и какое место займут более активные игры.</p>\n<p>Следующий шаг связан с помещением. У зала есть форма, высота, колонны и коммуникации. Они влияют на то, как разместится оборудование и сколько пространства останется вокруг. Большая конструкция должна вписаться по высоте под балками и вентиляцией. Между соседними играми нужны подходы и выходы. Эти участки занимают площадь, даже если в каталоге оборудования их никто отдельно не показывает.</p>\n<p>Теперь пройдём путь гостя. У входа семья останавливается, разбирается с вещами и ждёт остальных. Отсюда должен быть понятен дальнейший маршрут. Если для короткой остановки не оставили места, люди собираются в основном проходе. Поэтому входную стойку, гардероб и движение в зал рассматривают вместе. Это позволяет заранее увидеть, как несколько семей будут пользоваться одной входной зоной.</p>\n<p>Внутри парка занятия меняются. После лазания ребёнку может захотеться ролевой игры или интерактива. В большом пространстве важно, как перейти между этими участками и где заканчивается сама активность. В «ТикиТаки» есть многоуровневая игровая конструкция, батутная активность, ролевые зоны и интерактив. Такой состав удобно рассматривать через смену занятий в течение семейного дня.</p>\n<p>Но непрерывно играть готовы не все. Кто-то устал, кому-то нужно подождать ребёнка, а семье хочется собраться за столом. Поэтому отдых включают в общую планировку. Проверяют подход к мебели, свободный проход рядом и обзор с места взрослого. Наличие кафе или столов само по себе ещё не объясняет, насколько удобно ими пользоваться между играми.</p>\n<p>Отдельно стоит пройти сценарий дня рождения. Приглашённые приезжают в разное время, собираются в комнате, выходят играть и возвращаются к столу. Общий парк при этом принимает других посетителей. Нужно понять, где встречать гостей и как связать праздник с остальными активностями. Комнату нельзя оценить только по количеству столов: её расположение тоже влияет на организацию события.</p>\n<p>Есть и маршрут сотрудника. Он подходит к своей зоне, наблюдает за участниками, обращается к коллегам и берёт нужные материалы. При обслуживании потребуется доступ к оборудованию. Если смотреть только на впечатление посетителя, эта часть останется незаметной. Поэтому проект проверяют и с рабочей стороны, пока ещё можно изменить расположение элементов или оставить необходимое место.</p>\n<p>После такой проверки становится понятнее и состав предложения. Какие зоны входят в проект, какое оборудование требуется, что нужно подготовить в помещении и какие работы выполняются отдельно. Собственник может сравнить варианты по одному и тому же набору задач. Добавление новой активности тогда обсуждается вместе с изменениями вокруг неё, а не как отдельная покупка без последствий для зала.</p>\n<p>В итоге комплексный семейный парк собирается из связанных решений. В нём есть выбор занятий, возможность отдохнуть и понятные места для встречи. Для начала работы полезно подготовить план помещения и описать будущих гостей. Затем пройти несколько обычных ситуаций: первый визит, разные игры у детей, праздник и работа сотрудника. Именно эти ситуации показывают, как отдельные зоны станут одним парком.</p>"}, {"id": "YT-L03", "title": "Ниндзя-парк: как выбрать активности для разного возраста", "status": "Готов сценарий · ждёт озвучки и монтажа", "target_duration": "4–5 минут", "proposed_date": "2026-12-27", "description": "Ниндзя-парк: как выбрать активности для разного возраста.\n\nЧто учитывать при выборе заданий, аудитории и места для ниндзя-трассы.\n\nUNITRAMP проектирует и строит комплексные детские и семейные парки.\nhttps://unitramp.ru/", "text_html": "<p>Ниндзя-трасса выглядит как последовательность препятствий, но для будущего парка сначала нужно определить участников. Кто сюда придёт: дети с первым опытом, подростки, взрослые или несколько групп? От ответа зависит выбор заданий и место ниндзя-направления в общем пространстве. Красивое препятствие ещё не объясняет, кому оно подойдёт и как будет использоваться.</p>\n<p>На маршруте человек меняет движения. Где-то держится на подвесах, где-то проходит рукоход, ищет опору и переносит вес. Разнообразие связано с самими задачами. Если элементы отличаются только формой, а действия всё время повторяются, состав трассы стоит рассмотреть внимательнее. Для владельца важно понять, какие занятия он предлагает своей аудитории и как они сочетаются между собой.</p>\n<p>При этом возраст нельзя определять по впечатлению от общего вида. У конкретного оборудования есть характеристики и условия использования. Их проверяют вместе с предполагаемыми участниками. Взрослый атлет на сложном участке показывает один способ прохождения, но его движение нельзя автоматически предлагать ребёнку. Поэтому реальные кадры полезны для понимания механики, а выбор под аудиторию требует отдельной проверки.</p>\n<p>Следующий вопрос — как начинается прохождение. Человек подходит к заданию, разбирается, что делать, ждёт своей очереди. Потом заканчивает попытку и переходит дальше. Для каждого такого действия нужно пространство. Если учитывать только размеры конструкции, рядом может не остаться удобного подхода. Поэтому на плане рассматривают и само препятствие, и участок перед ним, и выход после задания.</p>\n<p>В семейном парке у ниндзя-зоны есть соседи. Рядом могут находиться другие активные игры или маршрут к более спокойному участку. Важно проверить, где движется участник и где проходят люди, которые сейчас не играют. Это особенно заметно, когда семья пришла с детьми разного возраста. Малыш не должен случайно попадать в начало сложного задания по дороге к своей зоне.</p>\n<p>Возможность выбирать занятие тоже требует продуманной организации. Один ребёнок готов пробовать более сложный элемент, другой хочет сначала посмотреть. Нужно понять, где можно подождать и как вернуться к взрослому. Разные маршруты или группы заданий рассматривают с учётом конкретного оборудования. Универсальную сложность для всех посетителей нельзя назначить одной надписью на входе.</p>\n<p>Отдельного внимания требует высота помещения. Подвесные элементы используют пространство над полом, а под потолком могут находиться балки и вентиляция. Поэтому общую высоту зала уточняют в местах будущей установки. Одновременно проверяют основание, покрытие и требования к свободному пространству. Эти данные нужны до выбора окончательной комплектации, чтобы оборудование и подготовка площадки были согласованы между собой.</p>\n<p>Теперь посмотрим на работу команды. Кто объясняет правила, откуда сотрудник видит участок и как подходит к оборудованию? Где хранятся инструкции и кому передают вопросы по эксплуатации? Эти задачи должны быть понятны к открытию. Состав подготовки зависит от выбранных активностей. Общее обещание, что сотрудники потом во всём разберутся, не заменяет конкретного порядка работы.</p>\n<p>Ниндзя-направление можно рассматривать и через разные посещения. Например, свободная игра семьи и организованное занятие используют пространство по-разному. Для группы нужно место сбора и понятная связь с остальными гостями. Это условный сценарий для проверки концепции, а не готовый рецепт загрузки. Сначала собственник определяет, какие посещения планирует, затем под них подбирают пространство и организацию.</p>\n<p>До согласования стоит пройти будущую зону по ролям. Вот новый участник впервые увидел препятствие. Вот рядом ждёт следующий. Вот взрослый ищет ребёнка, а сотруднику нужно подойти к своей рабочей точке. Такая проверка выявляет вопросы, которых нет в перечне оборудования. После неё можно уточнить состав трассы, порядок переходов и границы соседних активностей.</p>\n<p>Хороший выбор ниндзя-оборудования опирается на аудиторию, помещение и конкретные задания. Кадры прохождения помогают увидеть движения, но проекту нужны также характеристики элементов и понятная организация использования. Собственнику важно получить связную зону, в которой ясно, кто играет, как начинает и заканчивает задание и что происходит рядом. С этого стоит начинать обсуждение будущей трассы.</p>"}];
function decN(n){const k=n%100,m=n%10;return n+' '+((k<11||k>14)&&m===1?'публикация':(k<11||k>14)&&m>=2&&m<=4?'публикации':'публикаций');}
let DEC_QUERY='',DEC_WEEK='',DEC_NET='tg',DEC_ANCHOR='';
const DEC_PLATS=['Все','YouTube','ВК','Telegram','Instagram','Менеджеры'];
function decPlatform(r){if(r.channel==='YouTube Shorts'||r.channel==='YouTube')return'YouTube';if(['TG компании','TG Романа','TG Кирилла'].includes(r.channel))return'Telegram';if(['TG Екатерины','TG Оксаны'].includes(r.channel))return'Менеджеры';if(['VK','VK Клипы'].includes(r.channel))return'ВК';return'Instagram';}
function decLabel(ch){return({'TG компании':'Юнитрамп · канал компании','TG Романа':'Роман Сотников','TG Кирилла':'Кирилл Шувалов','TG Екатерины':'Екатерина Тюкавкина','TG Оксаны':'Оксана Журман','YouTube Shorts':'YouTube Shorts',YouTube:'YouTube · полный выпуск',VK:'Публикации ВК','VK Клипы':'ВК Клипы',Instagram:'Лента Instagram','IG Reels':'Instagram Reels'})[ch]||ch;}
function decCount(p){return p==='Все'?DEC_POSTS.length:DEC_POSTS.filter(r=>decPlatform(r)===p).length;}
function decEsc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function decFmt(n){return n==null?'—':new Intl.NumberFormat('ru-RU').format(n);}
function decAgg(rr,key){let known=rr.map(x=>x.metrics?.[key]).filter(x=>x!=null);return known.length?known.reduce((a,b)=>a+b,0):null;}
function decKpis(rr){return '<div class="kpis"><div class="kpi"><b>'+rr.length+'</b><span>публикаций</span></div><button class="kpi d6kpi '+(st.s==='v'?'selected':'')+'" data-s="v" aria-label="Сортировать по просмотрам"><b>'+decFmt(decAgg(rr,'views'))+'</b><span>просмотров ↗</span></button><button class="kpi d6kpi '+(st.s==='i'?'selected':'')+'" data-s="i" aria-label="Сортировать по взаимодействиям"><b>'+decFmt(decAgg(rr,'interactions'))+'</b><span>взаимодействий ↗</span></button></div>';}
function decSort(rr){let key=st.s==='v'?'views':st.s==='i'?'interactions':null;return rr.slice().sort((a,b)=>{let delta=key?((b.metrics?.[key]??-1)-(a.metrics?.[key]??-1)):0;return delta||(a.date+' '+a.time).localeCompare(b.date+' '+b.time)||a.id.localeCompare(b.id);});}
function decJump(id){const r=DEC_POSTS.find(x=>x.id===id);if(!r)return;st.p=decPlatform(r);st.f=r.channel;DEC_QUERY='';DEC_WEEK='';st.net='tg';DEC_ANCHOR=id;render();}
function decSummary(){
 const rr=DEC_POSTS;
 let h='<section class="s"><h2>Декабрь · месяц 3 <span class="muted">· 01–31.12.2026</span></h2>'+decKpis(rr)+'<p class="muted d6note">План на декабрь. Просмотры и взаимодействия заполняются после публикации.</p></section>';
 h+='<section class="s"><h2>По площадкам <span class="muted">· нажми на строку, чтобы открыть</span></h2><div class="tw"><table><thead><tr><th>Площадка</th><th class="n">Публикаций</th><th class="n">Просмотры</th><th class="n">Взаимодействия</th><th class="n">Среднее</th></tr></thead><tbody>';
 for(const p of ['YouTube','Telegram','ВК','Instagram','Менеджеры']){const rows=rr.filter(x=>decPlatform(x)===p);h+='<tr class="go" data-p="'+p+'"><td><b>'+p+'</b></td><td class="n">'+rows.length+'</td><td class="n">'+decFmt(decAgg(rows,'views'))+'</td><td class="n">'+decFmt(decAgg(rows,'interactions'))+'</td><td class="n">—</td></tr>';}
 h+='<tr class="tot"><td>Итого</td><td class="n">'+rr.length+'</td><td class="n">'+decFmt(decAgg(rr,'views'))+'</td><td class="n">'+decFmt(decAgg(rr,'interactions'))+'</td><td></td></tr></tbody></table></div></section>';
 h+='<section class="s"><h2>По каналам <span class="muted">· статистика каждого канала отдельно</span></h2><div class="tw"><table><thead><tr><th>Канал</th><th class="n">Публикаций</th><th class="n">Просмотры</th><th class="n">Взаимодействия</th></tr></thead><tbody>';
 for(const ch of ['TG компании','TG Романа','TG Кирилла','TG Екатерины','TG Оксаны']){const rows=rr.filter(x=>x.channel===ch);h+='<tr class="go" data-dec-channel="'+ch+'"><td><b>'+decEsc(decLabel(ch))+'</b></td><td class="n">'+rows.length+'</td><td class="n">'+decFmt(decAgg(rows,'views'))+'</td><td class="n">'+decFmt(decAgg(rows,'interactions'))+'</td></tr>';}
 h+='</tbody></table></div></section><section class="s"><h2>Все публикации <span class="muted">· '+rr.length+'</span></h2><div class="tools">'+sortTools()+'</div><div class="d6list">';
 for(const r of decSort(rr))h+='<button class="li d6jump" data-dec-id="'+r.id+'"><span class="d">'+r.date.slice(-2)+'.12</span><span class="pl"><span class="tag">'+decEsc(decLabel(r.channel))+'</span></span><span class="d6listtitle">'+decEsc(r.title)+' <span class="muted">· '+r.id+'</span></span><span class="v">'+decFmt(r.metrics?.views)+' <small>просм.</small> · '+decFmt(r.metrics?.interactions)+' <small>взаим.</small></span></button>';
 return h+'</div></section>';
}
function decMedia(r,alt){const items=(alt?r.instagram_media:r.media_items)||[];if(!items.length)return'';
 const imgs=items.filter(m=>m.kind!=='video');let h='';
 if(imgs.length){h+='<div class="d6gallery" role="region" aria-label="Медиа '+r.id+'"><div class="d6track" tabindex="0">'+imgs.map((m,i)=>'<figure><a href="'+decEsc(m.file)+'" target="_blank" rel="noopener"><img loading="lazy" src="'+decEsc(m.file)+'" alt="'+decEsc(r.title)+' · '+(i+1)+'"></a><figcaption>'+decEsc(m.caption||'')+' <a href="'+decEsc(m.file)+'" download>Скачать'+(imgs.length>1?' '+(i+1):'')+'</a></figcaption></figure>').join('')+'</div>'+(imgs.length>1?'<div class="d6gallerynav"><button data-gallery-prev aria-label="Предыдущий слайд">←</button><span>'+imgs.length+' фото / слайда · листайте</span><button data-gallery-next aria-label="Следующий слайд">→</button></div>':'')+'</div>';}
 for(const m of items.filter(m=>m.kind==='video'))h+='<div class="d6video"><video controls muted playsinline preload="none" poster="'+decEsc(m.poster)+'" src="'+decEsc(m.file)+'"></video><div class="d6downloads"><a href="'+decEsc(m.file)+'" download>Скачать видео</a><a href="'+decEsc(m.poster)+'" download>Скачать обложку</a></div></div>';
 return h;
}
function decPoll(r){if(!r.poll)return'';const p=r.poll,q='poll-q-'+r.id,o='poll-o-'+r.id;return '<details class="d7poll"><summary>Вопрос, варианты и настройки опроса</summary><div id="'+q+'"><b>'+decEsc(p.question)+'</b></div><div id="'+o+'">'+p.options.map(v=>decEsc(v)).join('\n')+'</div><p><small>Анонимный опрос · '+(p.multiple_answers?'Несколько ответов':'Один ответ')+'</small></p><div class="d5buttons"><button data-dec-copy="'+q+'">Скопировать вопрос</button><button data-dec-copy="'+o+'">Скопировать варианты</button></div></details>';}
function decCard(r){const alt=DEC_NET==='ig'&&r.instagram_media?.length,mx=DEC_NET==='max'&&r.max_text,id='d6-'+r.id;return '<article class="d5card" data-dec-card data-dec-week="'+Math.min(5,Math.floor((Number(r.date.slice(-2))-1)/7)+1)+'" id="'+decEsc(r.id)+'"><div class="pstat"><b>'+decEsc(r.id)+'</b><span>'+r.date.slice(-2)+'.12 · '+r.time+' ЕКБ</span><span class="tag">'+decEsc(alt?'Instagram':mx?'Макс':decLabel(r.channel))+'</span><span><b>'+decFmt(r.metrics?.views)+'</b> просм.</span><span><b>'+decFmt(r.metrics?.interactions)+'</b> взаим.</span></div><div class="d6cardbody"><h2>'+decEsc(r.title)+'</h2><div class="d5format">'+decEsc(alt?'Instagram · адаптация':mx?'Макс · тот же пост':r.format)+'</div>'+decMedia(r,alt)+'<div class="d5text" id="'+id+'">'+(alt?r.instagram_html:mx?r.max_html:r.text_html)+'</div>'+decPoll(r)+'<div class="d5buttons"><button onclick="cp(\''+id+'\',this)">Скопировать с оформлением</button><button onclick="cp(\''+id+'\',this,true)">Обычный текст</button></div>'+(r.channel==='YouTube Shorts'?decYtMeta(r):'')+(r.first_comment?'<details class="d6comment"><summary>Первый комментарий</summary><div id="'+id+'-comment">'+decEsc(r.first_comment)+'</div><button onclick="cp(\''+id+'-comment\',this,true)">Скопировать комментарий</button></details>':'')+'</div></article>';}
function viewDecember(M){
 if(st.p==='Все')return decSummary();
 let all=DEC_POSTS.filter(r=>decPlatform(r)===st.p),channels=[...new Set(all.map(x=>x.channel))];
 const aliases={'Канал Романа':'TG Романа','Канал Антона':'TG компании','Канал Кирилла':'TG Кирилла'};st.f=aliases[st.f]||st.f;if(!channels.includes(st.f))st.f='Все';
 let rows=all.filter(r=>st.f==='Все'||r.channel===st.f);const personal=st.f!=='Все'&&rows.some(r=>r.instagram_media?.length);
 DEC_NET=personal&&['ig','max'].includes(st.net)?st.net:'tg';
 let h='<section class="s"><h2>'+decEsc(st.f==='Все'?st.p:decLabel(st.f))+' <span class="muted">· Декабрь · 01–31.12.2026</span></h2>'+decKpis(rows)+'<div class="tools" style="margin-top:16px">'+sortTools()+'</div>';
 if(channels.length>1)h+='<div class="seg d6channels">'+['Все',...channels].map(ch=>'<button class="'+(st.f===ch?'on':'')+'" data-f="'+decEsc(ch)+'">'+(ch==='Все'?'Все каналы':decEsc(decLabel(ch)))+'</button>').join('')+'</div>';
 if(personal)h+='<div class="seg d6network"><button class="'+(DEC_NET==='tg'?'on':'')+'" data-dec-net="tg">Telegram</button><button class="'+(DEC_NET==='ig'?'on':'')+'" data-dec-net="ig">Instagram</button><button class="'+(DEC_NET==='max'?'on':'')+'" data-dec-net="max">Макс</button></div>';
 h+='<div class="d5filters"><label><span class="sr-only">Поиск по постам</span><input id="dec-query" type="search" placeholder="Найти пост, тему или объект" value="'+decEsc(DEC_QUERY)+'" oninput="decSearch(this.value)"></label><select aria-label="Неделя" onchange="decWeek(this.value)">'+[['','Весь декабрь'],['1','01–07 декабря'],['2','08–14 декабря'],['3','15–21 декабря'],['4','22–28 декабря'],['5','29–31 декабря']].map(([v,t])=>'<option value="'+v+'" '+(DEC_WEEK===v?'selected':'')+'>'+t+'</option>').join('')+'</select><span id="dec-found">'+decN(rows.length)+'</span></div></section>';
 if(!rows.length)return h+'<section class="s"><div class="empty">Публикаций на этой площадке пока нет.</div></section>';
 writeHash();return h+decSort(rows).map(decCard).join('')+(st.p==='YouTube'?decYtPipeline():'')+'<p id="dec-empty" class="d5empty" hidden>По этим условиям постов нет.</p>';
}
function decFilter(){let n=0;document.querySelectorAll('[data-dec-card]').forEach(a=>{const show=(!DEC_WEEK||a.dataset.decWeek===DEC_WEEK)&&(!DEC_QUERY||a.innerText.toLocaleLowerCase('ru').includes(DEC_QUERY.toLocaleLowerCase('ru')));a.hidden=!show;if(show)n++;});const el=document.getElementById('dec-found');if(el)el.textContent=decN(n);const empty=document.getElementById('dec-empty');if(empty)empty.hidden=n>0;if(DEC_ANCHOR){document.getElementById(DEC_ANCHOR)?.scrollIntoView({block:'start'});DEC_ANCHOR='';}}
function decSearch(v){DEC_QUERY=v;decFilter();}function decWeek(v){DEC_WEEK=v;decFilter();}
document.addEventListener('click',e=>{const t=e.target.closest('[data-dec-id],[data-dec-channel],[data-dec-net],[data-gallery-prev],[data-gallery-next]');if(!t)return;e.preventDefault();if(t.dataset.decId){decJump(t.dataset.decId);return;}if(t.dataset.decChannel){const r=DEC_POSTS.find(r=>r.channel===t.dataset.decChannel);st.p=decPlatform(r);st.f=r.channel;st.net='tg';DEC_QUERY='';DEC_WEEK='';render();scrollTo(0,0);}if(t.dataset.decNet){DEC_NET=t.dataset.decNet;st.net=DEC_NET;render();}if(t.hasAttribute('data-gallery-prev')||t.hasAttribute('data-gallery-next')){let track=t.closest('.d6gallery').querySelector('.d6track');track.scrollBy({left:(t.hasAttribute('data-gallery-prev')?-1:1)*track.clientWidth,behavior:'smooth'});}});
document.addEventListener('click',e=>{if(MONTHS[st.m]?.key!=='2026-12')return;const t=e.target.closest('[data-p],[data-f]');if(t){DEC_QUERY='';DEC_WEEK='';st.net='tg';}},true);

document.addEventListener('click',e=>{const b=e.target.closest('[data-dec-copy]');if(b){e.preventDefault();cp(b.dataset.decCopy,b,true);}});
function decYtMeta(r){const id='yt-meta-'+r.id;return '<details class="d7poll"><summary>Заголовок и теги YouTube</summary><div id="'+id+'-title"><b>'+decEsc(r.title)+'</b></div><div class="d5buttons"><button data-dec-copy="'+id+'-title">Скопировать заголовок</button></div><p>Теги · отдельное поле</p><div id="'+id+'-tags">'+decEsc((r.youtube_tags||[]).join(', '))+'</div><div class="d5buttons"><button data-dec-copy="'+id+'-tags">Скопировать теги</button></div><p><small>Превью показано для согласования. Для Shorts способ выбора обложки зависит от функций, доступных на канале.</small></p></details>';}
function decYtPipeline(){return '<section class="s"><h2>Полноформатные выпуски <span class="muted">· 3 в подготовке</span></h2><p>Ниже — сценарии и структура будущих выпусков. Готовых монтажей пока нет; в число подготовленных публикаций они не включены. Даты — предложения, после готовности видео их подтвердим.</p></section>'+DEC_YT_PIPELINE.map(r=>{const id='yt-long-'+r.id,day=r.proposed_date.slice(-2);return '<article class="d5card" id="'+r.id+'"><div class="pstat"><b>'+r.id+'</b><span>'+day+'.12 · предложенная дата</span><span class="tag">Полный выпуск</span></div><div class="d6cardbody"><h2>'+decEsc(r.title)+'</h2><p><strong>'+decEsc(r.status)+'</strong></p><p class="muted">'+decEsc(r.target_duration)+'</p><details class="d7poll"><summary>'+(r.id==='YT-L01'?'Структура выпуска':'Текст для озвучки')+'</summary><div class="d5text" id="'+id+'-script">'+r.text_html+'</div><div class="d5buttons"><button data-dec-copy="'+id+'-script">Скопировать сценарий</button></div></details><details class="d7poll"><summary>Заголовок и описание · черновик</summary><div id="'+id+'-title"><b>'+decEsc(r.title)+'</b></div><div class="d5buttons"><button data-dec-copy="'+id+'-title">Скопировать заголовок</button></div><div class="d5text" id="'+id+'-description">'+decEsc(r.description)+'</div><div class="d5buttons"><button data-dec-copy="'+id+'-description">Скопировать описание</button></div></details></div></article>';}).join('');}
